import{_ as o,o as t,c as i,ae as a}from"./chunks/framework.qNV68s4p.js";const u=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md","lastUpdated":1776334221000}'),l={name:"guide/troubleshooting.md"};function r(n,e,s,d,c,h){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>This page covers common issues encountered while integrating and using SweetEditor.</p><h2 id="decorations-keep-duplicating-while-scrolling" tabindex="-1">Decorations Keep Duplicating While Scrolling <a class="header-anchor" href="#decorations-keep-duplicating-while-scrolling" aria-label="Permalink to &quot;Decorations Keep Duplicating While Scrolling&quot;">​</a></h2><p>Cause:</p><ul><li>a viewport-scoped decoration provider uses <code>DecorationApplyMode.Merge</code></li></ul><p>Fix:</p><ul><li>use <code>DecorationApplyMode.ReplaceRange</code> for line-based viewport recomputation</li></ul><h2 id="completion-does-not-appear" tabindex="-1">Completion Does Not Appear <a class="header-anchor" href="#completion-does-not-appear" aria-label="Permalink to &quot;Completion Does Not Appear&quot;">​</a></h2><p>Checklist:</p><ul><li>a <code>CompletionProvider</code> is registered with <code>addCompletionProvider()</code></li><li>completion is manually triggered or a trigger character is supported</li><li>the controller is not currently in a conflicting state such as linked editing</li></ul><h2 id="inline-suggestion-does-not-show" tabindex="-1">Inline Suggestion Does Not Show <a class="header-anchor" href="#inline-suggestion-does-not-show" aria-label="Permalink to &quot;Inline Suggestion Does Not Show&quot;">​</a></h2><p>Checklist:</p><ul><li>call <code>controller.inlineSuggestions().show(...)</code></li><li>use a valid 0-based <code>line</code> and <code>column</code></li><li>ensure the document is loaded before showing the suggestion</li></ul><h2 id="theme-changes-do-not-apply" tabindex="-1">Theme Changes Do Not Apply <a class="header-anchor" href="#theme-changes-do-not-apply" aria-label="Permalink to &quot;Theme Changes Do Not Apply&quot;">​</a></h2><p>Checklist:</p><ul><li>call <code>controller.applyTheme(theme)</code></li><li>use <code>rememberEditorAppearance()</code> or <code>rememberEditorTheme()</code> consistently</li><li>keep behavior changes in <code>EditorSettings</code>, not in theme content</li></ul><h2 id="desktop-mouse-wheel-feels-wrong" tabindex="-1">Desktop Mouse Wheel Feels Wrong <a class="header-anchor" href="#desktop-mouse-wheel-feels-wrong" aria-label="Permalink to &quot;Desktop Mouse Wheel Feels Wrong&quot;">​</a></h2><p>Note:</p><ul><li>Desktop wheel normalization is handled at the platform layer</li></ul><h2 id="editor-looks-different-from-expected-theme" tabindex="-1">Editor Looks Different From Expected Theme <a class="header-anchor" href="#editor-looks-different-from-expected-theme" aria-label="Permalink to &quot;Editor Looks Different From Expected Theme&quot;">​</a></h2><p>Checklist:</p><ul><li>verify <code>controller.applyTheme(theme)</code> is called after the controller is ready</li><li>verify the expected <code>themeContent</code> keys are supported by the parser</li><li>verify behavior flags are configured in <code>EditorSettings</code> rather than theme content</li><li>verify custom <code>textStyles</code> names match the style aliases used by your highlighting data</li></ul><h2 id="related-docs" tabindex="-1">Related Docs <a class="header-anchor" href="#related-docs" aria-label="Permalink to &quot;Related Docs&quot;">​</a></h2><ul><li><a href="./architecture">Architecture</a></li><li><a href="./theme-appearance">Theme / Appearance</a></li><li><a href="./api-cookbook">API Cookbook</a></li><li><a href="./faq">FAQ</a></li></ul>',24)])])}const g=o(l,[["render",r]]);export{u as __pageData,g as default};
